def check_solution(a, b):
    # Original equation: a^2 + 2*3^b = a*(2^(b+1) - 1)
    lhs = a**2 + 2 * (3**b)
    rhs = a * ((2**(b+1)) - 1)
    return lhs == rhs

solutions_C = [(6, 3), (9, 3), (54, 5), (9, 5)]
results = {}
for a, b in solutions_C:
    results[(a, b)] = check_solution(a, b)

print(results)

def check_case_A(b):
    target = (2**(b+1)) - 1
    solutions = []
    for q in range(b + 1):
        lhs = (3**q) + 2 * (3**(b - q))
        if lhs == target:
            solutions.append(q)
    return solutions

def check_case_B(b):
    target = (2**(b+1)) - 1
    solutions = []
    for q in range(b + 1):
        lhs = 2 * (3**q) + (3**(b - q))
        if lhs == target:
            solutions.append(q)
    return solutions

# Search for b >= 11 up to b = 20
B_range = range(11, 21)
results = {}

print("--- Case A Solutions (q) ---")
for b in B_range:
    q_solutions = check_case_A(b)
    if q_solutions:
        results[b] = (True, q_solutions)
        print(f"b={b}: Solutions found for q in {q_solutions}")

print("\n--- Case B Solutions (q) ---")
for b in B_range:
    q_solutions = check_case_B(b)
    if q_solutions:
        results[b] = (False, q_solutions)
        print(f"b={b}: Solutions found for q in {q_solutions}")

# Check results for b=21 just to be extremely safe
b_check = 21
print(f"\n--- Checking b={b_check} ---")
print(f"Case A solutions for b={b_check}: {check_case_A(b_check)}")
print(f"Case B solutions for b={b_check}: {check_case_B(b_check)}")

